import { CommonModule } from '@angular/common';
import {
	Component,
	ElementRef,
	EventEmitter,
	forwardRef,
	HostListener,
	Injector,
	Input,
	OnChanges,
	OnDestroy,
	OnInit,
	Optional,
	Output
} from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { Subscription } from 'rxjs';

import {
	espdAbstractInputComponentInjectionToken,
	EspdAbstractInputDirective
} from 'espd-common/forms/api';
import { InputScaffoldComponent } from 'espd-common/forms/input-scaffold';
import { SearchComponent } from 'espd-common/forms/search';
import { MessageConfig, MessageModule, MessageService } from 'espd-common/i18n';
import { FilterPipe } from 'espd-common/utils';
import { MultiselectConfig } from './multiselect.config';
import { SelectItem, SelectItemType } from './multiselect.model';

@Component({
	selector: 'espd-multiselect',
	templateUrl: './multiselect.component.html',
	imports: [
		CommonModule,
		ReactiveFormsModule,
		FilterPipe,
		MessageModule,
		SearchComponent,
		InputScaffoldComponent
	],
	styleUrls: ['multiselect.component.scss'],
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => MultiselectComponent) }]
})
export class MultiselectComponent extends EspdAbstractInputDirective implements OnInit, OnChanges, OnDestroy {

	@Input()
	public unselectedListLabel?: string;

	@Input()
	public selectedListLabel?: string;

	@Input()
	public items?: Array<SelectItem>;

	@Input()
	public height?: string;

	@Input()
	public addRemoveAllEnabled: boolean = true;

	@Input()
	public filterEnabled: boolean = false;

	@Input()
	public filterPlaceholder: MessageConfig | string = '';

	@Output()
	public selected: EventEmitter<SelectItem> = new EventEmitter<SelectItem>();

	@Output()
	public deselected: EventEmitter<SelectItem> = new EventEmitter<SelectItem>();

	public SelectItemType = SelectItemType;

	public filter: string = '';
	public selectedList: Array<SelectItem> = [];
	public unselectedList: Array<SelectItem> = [];

	public get selectorHeight(): string {
		return this.height || this.config?.height || '200px';
	}

	private valueChangesSubscription?: Subscription;
	private focusedListName?: string;
	private focusedIndex?: number;

	constructor(
		public messageService: MessageService,
		@Optional() private config: MultiselectConfig | null,
		private element: ElementRef,
		injector: Injector
	) {
		super(injector);
	}

	@HostListener('keydown', ['$event'])
	public onKeyPress(event: KeyboardEvent): void {
		this.handleKeypress(event);
	}

	public ngOnInit(): void {
		super.ngOnInit();
		this.processChanges();
	}

	public ngOnChanges(): void {
		this.processChanges();
	}

	public processChanges(): void {
		if (this.control) {
			if (this.valueChangesSubscription) {
				this.valueChangesSubscription.unsubscribe();
			}
			this.valueChangesSubscription = this.control.valueChanges.subscribe(() => this.updateSelectedItems());
		}
		this.updateSelectedItems();
	}

	public ngOnDestroy(): void {
		super.ngOnDestroy();
		if (this.valueChangesSubscription) {
			this.valueChangesSubscription.unsubscribe();
		}
	}

	public onFocus(): void {
		this.focusOnList('unselected');
	}

	public isSelected(item: SelectItem): boolean {
		return this.selectedList?.includes(item) || false;
	}

	public onSelect(item: SelectItem): void {
		if (this.control) {
			const formValue: Array<any> = this.control.value || [];
			if (!formValue.includes(item.value)) {
				formValue.push(item.value);
				this.setFormControlValue(formValue);
				this.selected.next(item);
			}
		}
	}

	public onDeselect(item: SelectItem): void {
		if (this.control) {
			const formValue: Array<any> = this.control.value || [];
			const index: number = formValue.indexOf(item.value);
			if (index >= 0) {
				formValue.splice(index, 1);
				this.setFormControlValue(formValue);
				this.deselected.next(item);
			}
		}
	}

	public addAll(): void {
		this.items
			?.filter(item => !this.isSelected(item))
			.forEach(item => this.onSelect(item));
	}

	public removeAll(): void {
		this.items
			?.filter(item => this.isSelected(item))
			.forEach(item => this.onDeselect(item));
	}

	public setFilter(searched: string): void {
		this.filter = searched;
	}

	public unselectedFilter = (item: SelectItem): boolean => {
		if (this.filter) {
			const filter = this.filter.toLocaleLowerCase();
			return item.label.toLocaleLowerCase().includes(filter);
		} else {
			return true;
		}
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}

	private updateSelectedItems() {
		if (this.items && this.control) {
			const formValue: Array<any> = this.control.value || [];
			this.selectedList = this.items.filter(item => formValue.includes(item.value));
			this.unselectedList = this.items.filter(item => !formValue.includes(item.value));
		}
	}

	private setFormControlValue(value: Array<any>) {
		this.control.setValue(value);
		this.control.markAsTouched();
		this.control.markAsDirty();
	}

	private focusOnList(listName: string) {
		if (this.focusedListName !== listName) {
			this.focusedListName = listName;
			this.focusedIndex = undefined;
			this.setFocus();
		}
	}

	private handleKeypress(event: KeyboardEvent) {
		const key: string = event.key;
		let handled: boolean = false;
		if (key === 'ArrowUp') {
			if (this.focusedIndex != null) {
				this.focusedIndex = Math.max(0, this.focusedIndex - 1);
				this.setFocus();
			}
			handled = true;
		} else if (key === 'ArrowDown') {
			if (this.focusedList.length > 0) {
				if (this.focusedIndex == null) {
					this.focusedIndex = 0;
				} else {
					this.focusedIndex = Math.min(this.focusedList.length - 1, this.focusedIndex + 1);
				}
				this.setFocus();
			}
			handled = true;
		} else if (key === 'ArrowLeft') {
			this.focusOnList('unselected');
			handled = true;
		} else if (key === 'ArrowRight') {
			this.focusOnList('selected');
			handled = true;
		} else if (key === 'Home') {
			this.focusedIndex = 0;
			this.setFocus();
			handled = true;
		} else if (key === 'End') {
			this.focusedIndex = this.focusedList.length - 1;
			this.setFocus();
			handled = true;
		} else if (key === ' ') {
			this.moveItem();
			handled = true;
		} else if (key === 'Tab') {
			if (this.control) {
				this.control.markAsTouched();
			}
			this.focusedListName = undefined;
		}

		if (handled) {
			event.stopPropagation();
			event.preventDefault();
		}
	}

	private moveItem() {
		const selectedElement: HTMLElement | null = this.focusedListItemHtmlElement;
		if (selectedElement) {
			const selectedIndex: number = Array.prototype.indexOf.call(selectedElement.parentNode!.children, selectedElement);
			if (this.focusedListName === 'unselected') {
				this.onSelect(this.unselectedList[selectedIndex]);
				this.focusedListName = 'selected';
			} else {
				this.onDeselect(this.selectedList[selectedIndex]);
				this.focusedListName = 'unselected';
			}

			// this isn't the best, but not sure there's a better alternative given this unusual setup
			this.focusedIndex = undefined;
			this.setFocus();
		}
	}

	private setFocus() {
		if (this.focusedListName) {
			if (this.focusedIndex != null) {
				if (this.focusedList.length <= this.focusedIndex) {
					this.focusedIndex = Math.max(0, this.focusedList.length - 1);
				}

				const items = this.focusedListHtmlElement.querySelectorAll('li');
				// console.log(`selecting index ${this.focusedIndex} in ${this.focusedListName} items`);
				items[this.focusedIndex].focus();
			} else {
				this.focusedListHtmlElement.focus();
			}
		}
	}

	private get focusedList(): Array<SelectItem> {
		return this.focusedListName === 'unselected' ? this.unselectedList : this.selectedList;
	}

	private get focusedListHtmlElement(): HTMLElement {
		const elem: HTMLElement = this.element.nativeElement;
		const lists = elem.querySelectorAll('ul');
		return this.focusedListName === 'unselected' ? lists[0] : lists[1];
	}

	private get focusedListItemHtmlElement(): HTMLElement | null {
		const elem: HTMLElement = this.element.nativeElement;
		return elem.querySelector('ul li:focus');
	}
}